for p in plans:
 base=root/'generation/run/SE'/p['stem']
 assert not base.with_suffix('.png').exists()
 old=root/'generation/run/SE'/('12-v3.request.json' if p['stem']=='12-v4' else p['stem']+'.request.json')
 req=json.loads(old.read_text(encoding='utf-8'))
 req['startedAt']=None;req['status']='prepared_not_submitted';req['prompt']='generation/run/SE/'+p['stem']+'.prompt.txt'
 req['references']=p['refs'];req['submittedParameters']['referenced_image_paths']=p['refs'];req['referenceSha256']=[hashlib.sha256(Path(r).read_bytes()).hexdigest() for r in p['refs']]
 base.with_suffix('.prompt.txt').write_text(p['prompt'],encoding='utf-8')
